"""Read-only CPU artifact parity and synchronous peak-outlet comparison."""
import hashlib,json,sys
from pathlib import Path
import numpy as np
sys.path.insert(0,'benchmarks/phase7')
from compare_matched import field_metrics,mahleran_asc_interior
root=Path('agent_handoffs/tasks/phase7_matched_benchmark')
a=Path('outputs/phase7/syrup_matched_dt1');b=Path('outputs/phase7/syrup_matched_array_dt1')
sa=json.loads((a/'benchmark_summary.json').read_text());sb=json.loads((b/'benchmark_summary.json').read_text())
assert sa['provenance']['maple_syrup']==sb['provenance']['maple_syrup']
comparisons={}
for name in ['hydrograph.npz','final_state.npz','forcing.npz']:
 with np.load(a/name) as aa,np.load(b/name) as bb:
  assert set(aa.files)==set(bb.files)
  for k in aa.files:
   x,y=aa[k],bb[k];equal=np.array_equal(x,y)
   comparisons[name+':'+k]={'bitwise_equal_values':equal,'shape':list(x.shape)}
   if x.dtype.kind in 'fiu':
    comparisons[name+':'+k]['max_abs_difference']=float(np.max(np.abs(x.astype(float)-y.astype(float)))) if x.size else 0.
   if not equal:np.testing.assert_allclose(x,y,rtol=1e-10,atol=1e-12,err_msg=name+':'+k)
for s in [sa,sb]:assert s['sediment']['closure']['closed']
with np.load(root/'array_peak_outlet_snapshot.npz') as p:
 assert str(p['source_sha256'])==sa['provenance']['maple_syrup']['package_source_digest']['digest_sha256']
 metrics={}
 maps={}
 for fname,key,factor in [('depth','depth_m',1000),('veloc','velocity_m_s',1000)]:
  path=Path('outputs/phase7/mahleran_deterministic_ksat_run/Output')/(fname+'001.asc')
  ref=mahleran_asc_interior(np.loadtxt(path,skiprows=6),shape=(60,20));test=p[key]*factor
  metrics[fname]=field_metrics(ref,test);maps[fname+'_mahleran']=ref;maps[fname+'_syrup']=test
 peak_time=float(p['t_s'])
report={'scope':'CPU numerical artifact comparison and fields at each model own outlet peak; legacy exact unrounded peak time not saved, rounded peak plateau1328–1342s','source_sha256':sa['provenance']['maple_syrup']['package_source_digest']['digest_sha256'],'script_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),'all_values_bitwise_equal':all(v['bitwise_equal_values'] for v in comparisons.values()),'n_arrays':len(comparisons),'comparisons':comparisons,'syrup_snapshot_time_s':peak_time,'synchronous_spatial_metrics':metrics}
(root/'array_parity_and_spatial.json').write_text(json.dumps(report,indent=2)+'\n')
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
fig,ax=plt.subplots(2,3,figsize=(11,7),constrained_layout=True)
for i,f in enumerate(['depth','veloc']):
 ref=maps[f+'_mahleran'];test=maps[f+'_syrup'];mx=max(ref.max(),test.max())
 for j,(title,grid) in enumerate([('MAHLERAN at peak outlet',ref),('SYRUP at peak outlet',test),('SYRUP minus MAHLERAN',test-ref)]):
  kw={'cmap':'viridis','vmin':0,'vmax':mx} if j<2 else {'cmap':'coolwarm','vmin':-np.abs(test-ref).max(),'vmax':np.abs(test-ref).max()}
  im=ax[i,j].imshow(grid,origin='lower',aspect='auto',**kw);ax[i,j].set_title(title);fig.colorbar(im,ax=ax[i,j],label='depth (mm)' if i==0 else 'velocity (mm/s)')
fig.savefig(root/'peak_outlet_fields.png',dpi=150);plt.close(fig)
print(json.dumps({k:v for k,v in report.items() if k!='comparisons'},indent=2))

