"""Isolated CPU/device kernel parity and timing; not a coupled GPU event."""
import gc,json,time,statistics,hashlib
from pathlib import Path
import numpy as np
import cupy as cp
from maple_syrup.routing import build_routing_graph
from maple_syrup.sediment_physics import physics_grid_from_graph,plot1_sediment_parameters,sediment_physics_step
from maple_syrup.sediment_transport import transport_network,transport_step
from maple_syrup.provenance import source_tree_digest

def measure(fn,sync,repeats=5):
 sync();t=time.perf_counter();result=fn();sync();warm=time.perf_counter()-t
 times=[]
 for _ in range(repeats):
  sync();t=time.perf_counter();result=fn();sync();times.append(time.perf_counter()-t)
 return result,{'first_call_s':warm,'median_s':statistics.median(times),'samples_s':times}

def case(ny,nx):
 fields={};results={}
 for label,xp in [('cpu',np),('gpu',cp)]:
  z=np.repeat(np.arange(ny+2,dtype=float)[:,None]*.015,nx+2,axis=1);z+=np.abs(np.arange(nx+2)-(nx+1)/2)[None,:]*.03;z[:,[0,-1]]+=10
  exits=np.zeros(z.shape,bool);exits[0,:]=True
  g=build_routing_graph(z,exits,np.full((ny,nx),21.45),.5,xp=xp)
  grid=physics_grid_from_graph(g);net=transport_network(g);params=plot1_sediment_parameters(xp=xp)
  active=xp.broadcast_to(xp.asarray([.1,.15,.25,.25,.15,.1]),(ny,nx,6)).copy()
  memory=xp.zeros_like(active);h,v,rain,cover=[xp.full((ny,nx),f) for f in [.005,.02,1e-5,.2]]
  sync=cp.cuda.get_current_stream().synchronize if label=='gpu' else lambda:None
  laws,pt=measure(lambda:sediment_physics_step(params,grid,h,v,rain,cover,active,memory,1.),sync)
  mobile=xp.full_like(active,1e-4)
  trans,tt=measure(lambda:transport_step(net,mobile,laws.sediment_velocity_m_s,laws.deposition_rate_per_m,laws.settle_mask,1.),sync)
  fields[label]=[laws,trans];results[label]={'physics':pt,'transport':tt}
  if label=='gpu':results[label]['cupy_pool_reserved_bytes']=cp.get_default_memory_pool().total_bytes()
 comparisons={}
 for kind,index in [('physics',0),('transport',1)]:
  host=fields['cpu'][index];device=fields['gpu'][index]
  for name in host.__dataclass_fields__:
   a=getattr(host,name);b=getattr(device,name)
   if not isinstance(a,np.ndarray):continue
   b=cp.asnumpy(b)
   if a.dtype.kind=='b':assert np.array_equal(a,b),name
   else:np.testing.assert_allclose(b,a,rtol=1e-10,atol=1e-18,err_msg=name)
   comparisons[kind+'.'+name]=float(np.max(np.abs(a.astype(float)-b.astype(float)))) if a.size else 0
 return {'ny':ny,'nx':nx,'cells':ny*nx,'times':results,'max_absolute_differences':comparisons}

source=source_tree_digest(Path('src/maple_syrup')).digest_sha256
rows=[]
for ny,nx in [(60,20),(240,80),(480,160)]:
 rows.append(case(ny,nx));gc.collect();cp.get_default_memory_pool().free_all_blocks()
 print('finished',ny,nx,flush=True)
# New module creation during this isolated probe is not a physics change; record both hashes.
report={'scope':'fixed-input wet-law and lateral-transport kernels, excludes actual MAPLE bed, rainfall/routing, commits and coupled GPU event','cupy':cp.__version__,'numpy':np.__version__,'device':cp.cuda.runtime.getDeviceProperties(0)['name'].decode(),'source_before':source,'source_after':source_tree_digest(Path('src/maple_syrup')).digest_sha256,'parity_tolerance':{'rtol':1e-10,'atol':1e-18},'timing':'synchronized five samples, first call includes first-use setup/JIT; host-device setup excluded; validation synchronization included','memory':'CuPy pool reserved after calls; not whole-process GPU peak or driver allocations','script_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),'cases':rows}
Path('agent_handoffs/tasks/phase7_matched_benchmark/gpu_valley_after_fix.json').write_text(json.dumps(report,indent=2)+'\n')
